script:
// TASK: capture a PNG image of a Revit view so it can be SEEN / screenshotted, and hand the file
// back with Connector.Publish. Runs in a fresh scratch PROJECT document (a wall + isometric view as
// setup) so it touches no open model -- against your real project use the `Document` global and pick
// an existing view instead of the scratch one. The scratch project stays OPEN after the run.
var proj = Connector.CreateProjectDocument();
System.Console.WriteLine("cleanup-title=" + proj.Title + ";");
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }
Autodesk.Revit.DB.ElementId v3dTypeId = null;
foreach (Autodesk.Revit.DB.ViewFamilyType t in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.ViewFamilyType))) { if (t.ViewFamily == Autodesk.Revit.DB.ViewFamily.ThreeDimensional) { v3dTypeId = t.Id; break; } }

// 1. A view to capture (here a scratch isometric 3D view over one wall). Set the DisplayStyle INSIDE
//    a block; a shaded style is fine as long as ShadowViewsFileType is set (see step 2).
var vid = Connector.WithTransaction(proj, () => {
  Autodesk.Revit.DB.Wall.Create(proj, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0,0,0), new Autodesk.Revit.DB.XYZ(20,0,0)), level.Id, false);
  var v = Autodesk.Revit.DB.View3D.CreateIsometric(proj, v3dTypeId);
  v.DisplayStyle = Autodesk.Revit.DB.DisplayStyle.ShadingWithEdges;
  proj.Regenerate();
  return v.Id;
});
var view = proj.GetElement(vid) as Autodesk.Revit.DB.View3D;

// 2. Export the view to PNG BETWEEN blocks (ExportImage is self-transacting; inside a block it fails
//    script-target-must-not-be-modifiable). Set BOTH file-type fields: a SHADED view's image is
//    governed by ShadowViewsFileType, a wireframe/HLR view's by HLRandWFViewsFileType -- set only one
//    and the other display style writes NO file and throws NO exception.
string dir = Connector.ExportsDirectory;
string stem = System.IO.Path.Combine(dir, "view_capture");
var opt = new Autodesk.Revit.DB.ImageExportOptions();
opt.ExportRange = Autodesk.Revit.DB.ExportRange.SetOfViews;
opt.SetViewsAndSheets(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId>{ view.Id });
opt.HLRandWFViewsFileType = Autodesk.Revit.DB.ImageFileType.PNG;
opt.ShadowViewsFileType = Autodesk.Revit.DB.ImageFileType.PNG;
opt.ImageResolution = Autodesk.Revit.DB.ImageResolution.DPI_150;
opt.ZoomType = Autodesk.Revit.DB.ZoomFitType.FitToPage;
opt.PixelSize = 1024;
opt.FilePath = stem;   // Revit treats this as a STEM and APPENDS " - <ViewType> - <ViewName>.png"
proj.ExportImage(opt);

// 3. Find the file Revit actually wrote (its name differs from FilePath) and Publish it so it comes
//    back to the caller in files[].
var published = new System.Collections.Generic.List<string>();
foreach (var f in System.IO.Directory.GetFiles(dir, "view_capture*")) { Connector.Publish(f); published.Add(System.IO.Path.GetFileName(f)); }
return new { publishedFiles = published };
